contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint preDeposit, bytes calldata data) public payable {
        require(address(this).balance >= preDeposit);

        if (preDeposit > 0) {
            (bool ok, ) = address(c).call{value: preDeposit}(data);
            require(ok);
        }

        uint cBalanceBefore = address(c).balance;
        uint selfBalanceBefore = address(this).balance;

        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint cBalanceAfter = address(c).balance;
        uint selfBalanceAfter = address(this).balance;

        assert(!reverted && cBalanceAfter == 0 && selfBalanceAfter == selfBalanceBefore + cBalanceBefore);
    }

    receive() external payable {}
    fallback() external payable {}
}

