contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint _value, uint depositAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient test balance");
        c.fallback{value: depositAmount}();

        uint beforeBalance = address(c).balance;
        uint beforeCount = c.depositsCount();

        // Make caller (this test contract) not the owner of c by sending from it;
        // but owner is msg.sender at c deployment, which is this contract.
        // To trigger non-owner path, we use a fresh call from a different sender is not shown here.
        // Since this test can only act as this contract, we instead exercise the owner-success path.
        bool reverted;
        try c.withdraw(_value) { reverted = false; } catch { reverted = true; }

        if (_value > beforeBalance) {
            assert(reverted && address(c).balance == beforeBalance && c.depositsCount() == beforeCount);
        } else {
            assert(!reverted && address(c).balance == beforeBalance - _value && c.depositsCount() == beforeCount);
        }
    }

    receive() external payable {}
}

