contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint depositAmount, address target, uint sendValue, bytes memory data) public payable {
        require(address(this).balance >= depositAmount + sendValue, "not enough balance");

        // Make the test contract not the owner of c, so msg.sender for calls on c is a non-owner.
        (bool ok1,) = address(c).call{value: 0}(""); // just to be safe; not needed but no state change
        // Need to transfer ownership? owner is msg.sender at deployment, which is this contract.
        // To make a non-owner call, we call sendMoney from this contract, but msg.sender is this contract, which is the owner.
        // So we cannot be non-owner. Instead, the rule: owner's sendMoney call succeeds if target accepts and value <= balance; otherwise it reverts.
        // Let's focus on owner calls (msg.sender is owner).
        // So we test: for any target, value, data, if sendMoney reverts then balance and depositsCount are unchanged; if it succeeds, balance decreases by exactly value and depositsCount is unchanged (since sendMoney does not change depositsCount).

        uint balBefore = address(c).balance;
        uint depositsBefore = c.depositsCount();

        // Ensure c has enough balance to send sendValue.
        c.fallback{value: depositAmount}(); // depositAmount goes to c; depositsCount increments by 1.

        // Now re-read after deposit.
        balBefore = address(c).balance;
        depositsBefore = c.depositsCount();

        bool reverted;
        try c.sendMoney(target, sendValue, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = address(c).balance;
        uint depositsAfter = c.depositsCount();

        // General rule: depositsCount is unchanged by sendMoney.
        // And if not reverted, balance decreases exactly by sendValue.
        // If reverted, balance unchanged.
        assert(
            depositsAfter == depositsBefore &&
            (reverted ? balAfter == balBefore : balAfter == balBefore - sendValue)
        );
    }

    receive() external payable {}
}

