contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint extraEther) public payable {
        require(address(this).balance >= extraEther, "insufficient balance to forward");
        // Optionally deposit extra Ether into C to influence its balance; this is an owner fallback deposit.
        if (extraEther > 0) {
            (bool depositOk, ) = address(c).call{value: extraEther}("");
            require(depositOk, "deposit failed");
        }

        uint cBalanceBefore = address(c).balance;
        uint depositsCountBefore = c.depositsCount();
        uint testBalanceBefore = address(this).balance;

        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint cBalanceAfter = address(c).balance;
        uint depositsCountAfter = c.depositsCount();
        uint testBalanceAfter = address(this).balance;

        // The rule: withdrawAll() reverts exactly when C has zero balance;
        // otherwise it succeeds, empties C (cBalanceAfter == 0),
        // transfers exactly cBalanceBefore Ether to the test contract,
        // and depositsCount is unchanged in both cases.
        assert(
            (reverted == (cBalanceBefore == 0)) &&
            (reverted || (cBalanceAfter == 0 && testBalanceAfter == testBalanceBefore + cBalanceBefore)) &&
            (depositsCountAfter == depositsCountBefore)
        );
    }
}

